PRAGMA foreign_keys = ON;
CREATE TABLE seo_keywords (id INTEGER PRIMARY KEY AUTOINCREMENT,keyword TEXT NOT NULL UNIQUE,category TEXT NOT NULL DEFAULT '',intent TEXT NOT NULL DEFAULT '',priority TEXT NOT NULL DEFAULT 'Low',is_primary INTEGER NOT NULL DEFAULT 0,country TEXT NOT NULL DEFAULT 'All',target_city TEXT NOT NULL DEFAULT '',device TEXT NOT NULL DEFAULT 'All',target_page TEXT NOT NULL DEFAULT '',mapped_page TEXT NOT NULL DEFAULT '',mapping_intent TEXT NOT NULL DEFAULT '',mapping_market TEXT NOT NULL DEFAULT '',mapping_confidence TEXT NOT NULL DEFAULT '',mapping_notes TEXT,assigned_user_id INTEGER,active INTEGER NOT NULL DEFAULT 1,recommended_action TEXT,source TEXT NOT NULL DEFAULT 'manual',source_detail TEXT NOT NULL DEFAULT '',source_notes TEXT,original_assignee TEXT NOT NULL DEFAULT '',original_latest_date TEXT,source_snapshot_json TEXT,source_row_hash TEXT UNIQUE,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(assigned_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE seo_observations (id INTEGER PRIMARY KEY AUTOINCREMENT,observation_key TEXT NOT NULL UNIQUE,property_id TEXT NOT NULL,data_date TEXT,period_start TEXT NOT NULL,period_end TEXT NOT NULL,search_type TEXT NOT NULL DEFAULT 'web',grain TEXT NOT NULL,query_text TEXT NOT NULL DEFAULT '',page_url TEXT NOT NULL DEFAULT '',country TEXT NOT NULL DEFAULT 'all',device TEXT NOT NULL DEFAULT 'all',clicks REAL NOT NULL DEFAULT 0,impressions REAL NOT NULL DEFAULT 0,ctr REAL,position REAL,source TEXT NOT NULL,source_batch TEXT,imported_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_seo_obs_date ON seo_observations(data_date,grain);
CREATE INDEX idx_seo_obs_query ON seo_observations(query_text,data_date);
CREATE INDEX idx_seo_obs_page ON seo_observations(page_url,data_date);
CREATE TABLE seo_import_batches (id INTEGER PRIMARY KEY AUTOINCREMENT,source_name TEXT NOT NULL,file_hash TEXT NOT NULL,rows_seen INTEGER NOT NULL DEFAULT 0,rows_added INTEGER NOT NULL DEFAULT 0,imported_by INTEGER,imported_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(source_name,file_hash),FOREIGN KEY(imported_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE seo_google_connections (id INTEGER PRIMARY KEY,property_id TEXT NOT NULL,refresh_token_enc TEXT NOT NULL,access_token_enc TEXT,expires_at TEXT,connected_by INTEGER NOT NULL,connected_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(connected_by) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE seo_refresh_runs (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,property_id TEXT NOT NULL DEFAULT '',started_at TEXT DEFAULT CURRENT_TIMESTAMP,finished_at TEXT,status TEXT NOT NULL DEFAULT 'running',data_date TEXT,grain TEXT NOT NULL DEFAULT 'property',start_row INTEGER NOT NULL DEFAULT 0,rows_processed INTEGER NOT NULL DEFAULT 0,rows_added INTEGER NOT NULL DEFAULT 0,rows_updated INTEGER NOT NULL DEFAULT 0,message TEXT NOT NULL DEFAULT '',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE seo_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT,keyword_id INTEGER,page_url TEXT NOT NULL DEFAULT '',assigned_user_id INTEGER,priority TEXT NOT NULL DEFAULT 'Medium',status TEXT NOT NULL DEFAULT 'To Do',due_date TEXT,completion_notes TEXT,completed_at TEXT,created_by INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(keyword_id) REFERENCES seo_keywords(id) ON DELETE SET NULL,FOREIGN KEY(assigned_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE seo_dashboard_cache (cache_key TEXT PRIMARY KEY,payload_json TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE seo_settings (setting_key TEXT PRIMARY KEY,setting_value TEXT NOT NULL,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE seo_weekly_summaries (id INTEGER PRIMARY KEY AUTOINCREMENT,source_key TEXT NOT NULL UNIQUE,week_start TEXT NOT NULL,period_end TEXT NOT NULL,clicks REAL,impressions REAL,ctr REAL,position REAL,source TEXT NOT NULL);
